TABLES = (
    "embeddings, ai_output_log, reports, call_members, calls, push_subscriptions, notifications, messages, "
    "conversation_members, conversations, highlight_stories, highlights, story_views, stories, comments, saves, "
    "collections, post_hashtags, hashtags, likes, post_media, posts, blocked_hashes, media_assets, follows, "
    "audit_log, blocks, oauth_clients, refresh_tokens, profiles, users"
)


def upgrade() -> None:
    # asyncpg executes one statement per call, so the script is split on statement ends.
    conn = op.get_bind()
    for stmt in SCHEMA.split(";\n"):
        if stmt.strip():
            conn.exec_driver_sql(stmt.strip())
    # Monthly partitions from the current month. Celery Beat keeps creating future months.
    year, month = date.today().year, date.today().month
    for _ in range(4):
        next_year, next_month = (year + 1, 1) if month == 12 else (year, month + 1)
        for table in ("messages", "notifications"):
            conn.exec_driver_sql(
                f"CREATE TABLE {table}_{year}_{month:02d} PARTITION OF {table} "
                f"FOR VALUES FROM ('{year}-{month:02d}-01') TO ('{next_year}-{next_month:02d}-01')"
            )
        year, month = next_year, next_month


def downgrade() -> None:
    op.get_bind().exec_driver_sql(f"DROP TABLE IF EXISTS {TABLES} CASCADE")
